  3	import type { Tag } from "@/lib/nav";
  4	
  5	export const TagBadge = ({ tag }: { tag?: Tag }) => {
  6	  if (!tag) return null;
  7	  const map = { new: ["tag-new", "New"], soon: ["tag-soon", "Coming soon"], beta: ["tag-beta", "Beta"] } as const;
  8	  const [cls, label] = map[tag];
  9	  return <i className={`tag ${cls}`}>{label}</i>;
 10	};
 11	
 12	export interface Cta { label: string; href: string }
 13	
 14	export function Hero({ eyebrow, badge, title, sub, ctas = [], accent }: {
 15	  eyebrow?: string; badge?: string; title: string; sub?: string; ctas?: Cta[]; accent?: string;
 16	}) {
 17	  const glow = accent
 18	    ? { background: `radial-gradient(50% 50% at 50% 50%, ${accent}1c 0%, ${accent}0d 44%, transparent 72%)` }
 19	    : undefined;
 20	  return (
 21	    <section className="hero" style={accent ? ({ ["--acc" as string]: accent }) : undefined}>
 22	      <div className="hero-bg" aria-hidden>
 23	        <div className="hero-grid" />
 24	        <div className="hero-glow" style={glow} />
 25	      </div>
 26	      <div className="wrap hero-content">
 27	        {eyebrow && <div className="eyebrow rise">{badge && <b>{badge}</b>}{eyebrow}</div>}
 28	        <h1 className="grad rise">{title}</h1>
 29	        {sub && <p className="hero-sub rise">{sub}</p>}
 30	        {ctas.length > 0 && (
 31	          <div className="btn-row rise">
 32	            {ctas.map((c, i) => (
 33	              <Link key={c.href + i} className={`btn btn-lg ${i === 0 ? "btn-primary" : "btn-secondary"}`} href={c.href}>{c.label}</Link>
 34	            ))}
 35	          </div>
 36	        )}
 37	      </div>
 38	    </section>
 39	  );
 40	}
 41	
 42	export function SectionHead({ title, sub, center }: { title: string; sub?: string; center?: boolean }) {
 43	  return (
 44	    <div className={center ? "center" : ""} style={{ marginBottom: 40, ...(center ? { maxWidth: 640, marginLeft: "auto", marginRight: "auto" } : {}) }}>
 45	      <h2 className="grad">{title}</h2>
 46	      {sub && <p className="lede" style={{ marginTop: 14, ...(center ? { marginLeft: "auto", marginRight: "auto" } : {}) }}>{sub}</p>}
 47	    </div>
 48	  );
 49	}
 50	
 51	export interface CardItem { title: string; desc: string; icon?: ReactElement; accent?: string; tag?: Tag; href?: string }
 52	
 53	export function Cards({ items, cols = 3 }: { items: CardItem[]; cols?: 2 | 3 | 4 }) {
 54	  return (
 55	    <div className={`grid g${cols}`}>
 56	      {items.map((c) => {
 57	        const inner = (
 58	          <>
 59	            {c.icon && <span className="ico">{c.icon}</span>}
 60	            <h4>{c.title}<TagBadge tag={c.tag} /></h4>
 61	            <p>{c.desc}</p>
 62	          </>
 63	        );
 64	        const cls = `card ${c.accent ? "card-accent" : ""}`;
 65	        const style = c.accent ? ({ ["--acc" as string]: c.accent }) : undefined;
 66	        return c.href
 67	          ? <Link key={c.title} className={cls} style={style} href={c.href}>{inner}</Link>
 68	          : <div key={c.title} className={cls} style={style}>{inner}</div>;
 69	      })}
 70	    </div>
 71	  );
 72	}
 73	
 74	export function StatBand({ stats }: { stats: { n: string; l: string }[] }) {
 75	  return (
 76	    <div className="stat-band">
 77	      {stats.map((s) => <div className="stat" key={s.n + s.l}><b>{s.n}</b><span>{s.l}</span></div>)}
 78	    </div>
 79	  );
 80	}
 81	
 82	export function Term({ title, html }: { title: string; html: string }) {
 83	  return (
 84	    <div className="term">
 85	      <div className="term-bar"><i className="dot" /><i className="dot" /><i className="dot" /><span className="term-title">{title}</span></div>
 86	      <div className="term-body" dangerouslySetInnerHTML={{ __html: html }} />
 87	    </div>
 88	  );
 89	}
